   279→	return settings.LogLevel
   280→}
   281→
   282→// IsMultiSessionWarningDisabled checks if multi-session warnings are disabled.
   283→// Returns false (show warnings) by default if settings cannot be loaded or the key is missing.
   284→func IsMultiSessionWarningDisabled() bool {
   285→	settings, err := LoadEntireSettings()
   286→	if err != nil {
   287→		return false // Default: show warnings
   288→	}
   289→	if settings.StrategyOptions == nil {
   290→		return false
   291→	}
   292→	if disabled, ok := settings.StrategyOptions["disable_multisession_warning"].(bool); ok {
   293→		return disabled
   294→	}
   295→	return false
   296→}
   297→
   298→// GetAgentsWithHooksInstalled returns names of agents that have hooks installed.
   299→func GetAgentsWithHooksInstalled() []agent.AgentName {
   300→	var installed []agent.AgentName
   301→	for _, name := range agent.List() {
   302→		ag, err := agent.Get(name)
   303→		if err != nil {
   304→			continue
   305→		}
   306→		if hs, ok := ag.(agent.HookSupport); ok && hs.AreHooksInstalled() {
   307→			installed = append(installed, name)
   308→		}
   309→	}
   310→	return installed
   311→}
   312→
   313→// JoinAgentNames joins agent names into a comma-separated string.
   314→func JoinAgentNames(names []agent.AgentName) string {
   315→	strs := make([]string, len(names))
   316→	for i, n := range names {
   317→		strs[i] = string(n)
   318→	}
   319→	return strings.Join(strs, ",")
   320→}
