	defer func() {
		if originalEnv == "" {
			os.Unsetenv("ENTIRE_VERSION_CHECK_OPTOUT") //nolint:errcheck
		} else {
			os.Setenv("ENTIRE_VERSION_CHECK_OPTOUT", originalEnv) //nolint:errcheck
		}
