package versioncheck

import (
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"testing"
	"time"
)

func TestCompareVersions(t *testing.T) {
	tests := []struct {
		current string
		latest  string
		want    bool
		desc    string
	}{
		// Standard semver cases
		{"1.0.0", "1.0.1", true, "patch version bump"},
		{"1.0.0", "1.1.0", true, "minor version bump"},
		{"1.0.0", "2.0.0", true, "major version bump"},
		{"1.0.1", "1.0.0", false, "current is newer"},
		{"2.0.0", "1.9.9", false, "current major is higher"},
		{"1.0.0", "1.0.0", false, "same version"},

		// v-prefix handling
		{"v1.0.0", "v1.0.1", true, "with v prefix"},
		{"v1.0.0", "1.0.1", true, "mixed v prefix"},
		{"1.0.0", "v1.0.1", true, "mixed v prefix reversed"},

		// Empty versions
		{"", "1.0.0", false, "empty current"},
		{"1.0.0", "", false, "empty latest"},
		{"", "", false, "both empty"},

		// Complex versions with pre-release suffixes (numeric part extracted)
		{"1.0.0", "1.0.1rc1", true, "prerelease in latest"},
		{"1.0.0rc1", "1.0.0", true, "prerelease in current"},

		// Single component versions
		{"1", "2", true, "single component"},
		{"1.5", "2.0", true, "two components"},
	}

	for _, tt := range tests {
		t.Run(tt.desc, func(t *testing.T) {
			got := isOutdated(tt.current, tt.latest)
			if got != tt.want {
				t.Errorf("isOutdated(%q, %q) = %v, want %v", tt.current, tt.latest, got, tt.want)
			}
		})
	}
}

func TestParseVersion(t *testing.T) {
	tests := []struct {
		version string
		want    [3]int
		desc    string
	}{
		{"1.2.3", [3]int{1, 2, 3}, "standard version"},
		{"v1.2.3", [3]int{1, 2, 3}, "version with v prefix"},
		{"10.20.30", [3]int{10, 20, 30}, "two digit numbers"},
		{"1.2", [3]int{1, 2, 0}, "missing patch"},
		{"1", [3]int{1, 0, 0}, "only major"},
		{"1.2.3rc1", [3]int{1, 2, 3}, "version with suffix"},
		{"0.0.0", [3]int{0, 0, 0}, "zero version"},
	}

	for _, tt := range tests {
		t.Run(tt.desc, func(t *testing.T) {
			got, err := parseVersion(tt.version)
			if err != nil {
				t.Errorf("parseVersion(%q) error = %v", tt.version, err)
				return
			}
			if got != tt.want {
				t.Errorf("parseVersion(%q) = %v, want %v", tt.version, got, tt.want)
			}
		})
	}
}

func TestShouldFetchLatest(t *testing.T) {
	tests := []struct {
		cache   *VersionCache
		current string
		want    bool
		desc    string
	}{
		// Empty cache - should fetch
		{&VersionCache{}, "1.0.0", true, "empty cache"},
		{&VersionCache{LatestVersion: ""}, "1.0.0", true, "empty latest version"},

		// Version changed - should fetch
		{&VersionCache{CurrentVersion: "1.0.0", LatestVersion: "1.0.1", LastCheckTime: time.Now()},
			"1.0.1", true, "version changed (CLI upgraded)"},

		// Cache is fresh - should not fetch
		{&VersionCache{CurrentVersion: "1.0.0", LatestVersion: "1.0.1", LastCheckTime: time.Now()},
			"1.0.0", false, "fresh cache"},

		// Cache is stale (>24 hours) - should fetch
		{&VersionCache{CurrentVersion: "1.0.0", LatestVersion: "1.0.1", LastCheckTime: time.Now().Add(-25 * time.Hour)},
			"1.0.0", true, "stale cache (>24h)"},

		// Cache is almost stale but not quite - should not fetch
		{&VersionCache{CurrentVersion: "1.0.0", LatestVersion: "1.0.1", LastCheckTime: time.Now().Add(-23 * time.Hour)},
			"1.0.0", false, "recent cache (<24h)"},
	}

	for _, tt := range tests {
		t.Run(tt.desc, func(t *testing.T) {
			got := shouldFetchLatest(tt.cache, tt.current)
			if got != tt.want {
				t.Errorf("shouldFetchLatest(..., %q) = %v, want %v", tt.current, got, tt.want)
			}
		})
	}
}

func TestParseGitHubRelease(t *testing.T) {
	tests := []struct {
		jsonBody string
		want     string
		wantErr  bool
		desc     string
	}{
		{
			`{"tag_name": "v1.2.3", "prerelease": false}`,
			"v1.2.3",
			false,
			"valid release",
		},
		{
			`{"tag_name": "v1.2.3", "prerelease": true}`,
			"",
			true,
			"prerelease filtered",
		},
		{
			`{"tag_name": "", "prerelease": false}`,
			"",
			true,
			"empty tag name",
		},
		{
			`invalid json`,
			"",
			true,
			"invalid JSON",
		},
	}

	for _, tt := range tests {
		t.Run(tt.desc, func(t *testing.T) {
			got, err := parseGitHubRelease([]byte(tt.jsonBody))
			if (err != nil) != tt.wantErr {
				t.Errorf("parseGitHubRelease() error = %v, wantErr %v", err, tt.wantErr)
				return
			}
			if got != tt.want {
				t.Errorf("parseGitHubRelease() = %q, want %q", got, tt.want)
			}
		})
	}
}

func TestCacheReadWrite(t *testing.T) {
	// Create a temporary directory for the test
	tmpDir := t.TempDir()

	// Create config directory structure
	configDir := filepath.Join(tmpDir, globalConfigDirName)
	if err := os.MkdirAll(configDir, 0o755); err != nil {
		t.Fatalf("Failed to create config dir: %v", err)
	}

	// Test saving and loading cache directly to temp directory
	originalCache := &VersionCache{
		LastCheckTime:  time.Now().Round(time.Second), // Round to second for JSON consistency
		LatestVersion:  "v1.2.3",
		CurrentVersion: "v1.2.0",
	}

	// Write cache manually to temp directory
	filePath := filepath.Join(configDir, cacheFileName)
	data, err := json.MarshalIndent(originalCache, "", "  ")
	if err != nil {
		t.Fatalf("json.MarshalIndent() error = %v", err)
	}

	if err := os.WriteFile(filePath, data, 0o644); err != nil {
		t.Fatalf("WriteFile() error = %v", err)
	}

	// Load and verify
	loadedData, err := os.ReadFile(filePath)
	if err != nil {
		t.Fatalf("ReadFile() error = %v", err)
	}

	var loaded VersionCache
	if err := json.Unmarshal(loadedData, &loaded); err != nil {
		t.Fatalf("json.Unmarshal() error = %v", err)
	}

	// Verify the loaded cache matches
	if loaded.LatestVersion != originalCache.LatestVersion {
		t.Errorf("LatestVersion = %q, want %q", loaded.LatestVersion, originalCache.LatestVersion)
	}
	if loaded.CurrentVersion != originalCache.CurrentVersion {
		t.Errorf("CurrentVersion = %q, want %q", loaded.CurrentVersion, originalCache.CurrentVersion)
	}

	// Verify file exists
	if _, err := os.Stat(filePath); err != nil {
		t.Errorf("cache file not found at %s: %v", filePath, err)
	}
}

func TestEnsureGlobalConfigDir(t *testing.T) {
	// This test verifies that the directory creation logic works
	// We test the actual os.MkdirAll behavior by creating a temp directory structure

	tmpDir := t.TempDir()
	configDir := filepath.Join(tmpDir, globalConfigDirName)

	// Verify the directory doesn't exist yet
	if _, err := os.Stat(configDir); err == nil {
		t.Fatalf("directory already exists before test")
	}

	// Simulate the ensureGlobalConfigDir logic
	if err := os.MkdirAll(configDir, 0o755); err != nil {
		t.Fatalf("MkdirAll() error = %v", err)
	}

	// Verify directory was created
	info, err := os.Stat(configDir)
	if err != nil {
		t.Fatalf("directory not created: %v", err)
	}

	// Verify it's a directory
	if !info.IsDir() {
		t.Errorf("path is not a directory")
	}

	// Verify permissions (on Unix systems)
	// The directory should be readable/writable/executable by owner
	if mode := info.Mode(); (mode & 0o700) != 0o700 {
		t.Errorf("directory permissions = %o, expected at least 0o700", mode)
	}
}

func TestFetchLatestVersionWithMockServer(t *testing.T) {
	// Create a mock HTTP server
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		// Verify headers
		if r.Header.Get("Accept") != "application/vnd.github+json" {
			t.Errorf("Accept header = %q, want application/vnd.github+json", r.Header.Get("Accept"))
		}

		// Return a mock GitHub release
		release := GitHubRelease{
			TagName:    "v1.2.3",
			Prerelease: false,
		}
		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(release) //nolint:errcheck
	}))
	defer server.Close()

	// Mock the githubAPIURL (this would normally be done at the module level)
	// For this test, we'll just verify the HTTP call works by creating a custom function
	// Note: In real usage, this would use the actual GitHub API

	// For now, we'll test the parseGitHubRelease function which is the core parsing logic
	body := []byte(`{"tag_name": "v1.2.3", "prerelease": false}`)
	version, err := parseGitHubRelease(body)
	if err != nil {
		t.Errorf("parseGitHubRelease() error = %v", err)
	}
	if version != "v1.2.3" {
		t.Errorf("parseGitHubRelease() = %q, want v1.2.3", version)
	}
}

func TestIsOutdated(t *testing.T) {
	tests := []struct {
		current string
		latest  string
		want    bool
		desc    string
	}{
		{"1.0.0", "1.1.0", true, "minor bump"},
		{"1.0.0", "1.0.0", false, "same version"},
		{"1.1.0", "1.0.0", false, "current is newer"},
		{"", "1.0.0", false, "empty current"},
		{"1.0.0", "", false, "empty latest"},
	}

	for _, tt := range tests {
		t.Run(tt.desc, func(t *testing.T) {
			got := isOutdated(tt.current, tt.latest)
			if got != tt.want {
				t.Errorf("isOutdated(%q, %q) = %v, want %v", tt.current, tt.latest, got, tt.want)
			}
		})
	}
}

func TestIsVersionCheckDisabled(t *testing.T) {
	// Store original env var
	originalEnv := os.Getenv("ENTIRE_VERSION_CHECK_OPTOUT")
	defer func() {
		if originalEnv == "" {
			os.Unsetenv("ENTIRE_VERSION_CHECK_OPTOUT")
		} else {
			os.Setenv("ENTIRE_VERSION_CHECK_OPTOUT", originalEnv)
		}
	}()

	tests := []struct {
		envValue string
		want     bool
		desc     string
	}{
		{"", false, "env var not set"},
		{"1", true, "env var set to 1"},
		{"true", true, "env var set to any non-empty value"},
	}

	for _, tt := range tests {
		t.Run(tt.desc, func(t *testing.T) {
			if tt.envValue == "" {
				os.Unsetenv("ENTIRE_VERSION_CHECK_OPTOUT")
			} else {
				os.Setenv("ENTIRE_VERSION_CHECK_OPTOUT", tt.envValue)
			}

			got := isVersionCheckDisabled()
			if got != tt.want {
				t.Errorf("isVersionCheckDisabled() = %v, want %v", got, tt.want)
			}
		})
	}
}

