func CheckAndNotify(cmd *cobra.Command, currentVersion string) {
	// Skip checks if disabled via env var or settings
	if isVersionCheckDisabled() {
		return
	}

	// Skip checks for dev builds
	if currentVersion == "dev" || currentVersion == "" {
		return
	}

	// Ensure the global config directory exists
	if err := ensureGlobalConfigDir(); err != nil {
		// Silent failure - don't block CLI operations
		return
	}

	// Load the cache
	cache, err := loadCache()
	if err != nil {
		// Cache doesn't exist or is corrupted - will be fetched fresh
		cache = &VersionCache{
			CurrentVersion: currentVersion,
		}
	}

	// Determine if we should fetch the latest version
	if !shouldFetchLatest(cache, currentVersion) {
		// Cache is still valid - check if we're outdated
		if isOutdated(cache.CurrentVersion, cache.LatestVersion) {
			printNotification(cmd, cache.CurrentVersion, cache.LatestVersion)
		}
