package versioncheck

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"time"

	"entire.io/cli/cmd/entire/cli/logging"
	"github.com/spf13/cobra"
)

// CheckAndNotify performs a version check and notifies the user if a newer version is available.
// This is the main entry point for the version check system.
// The function is silent on all errors to avoid interrupting CLI operations.
func CheckAndNotify(cmd *cobra.Command, currentVersion string) {
	// Skip checks for hidden commands
	if cmd.Hidden {
		return
	}

	// Skip checks for dev builds
	if currentVersion == "dev" || currentVersion == "" {
		return
	}

	// Ensure the global config directory exists
	if err := ensureGlobalConfigDir(); err != nil {
		// Silent failure - don't block CLI operations
		return
	}

	// Load the cache to check when we last fetched
	cache, err := loadCache()
	if err != nil {
		cache = &VersionCache{}
	}

	// Skip if we checked recently (within 24 hours)
	if time.Since(cache.LastCheckTime) < checkInterval {
		return
	}

	// Fetch the latest version from GitHub API
	latestVersion, err := fetchLatestVersion()
	if err != nil {
		// Network error or timeout - silently skip
		logging.Debug(context.Background(), "version check: failed to fetch latest version",
			"error", err.Error())
		return
	}

	// Update cache with new check time
	cache.LastCheckTime = time.Now()
	if err := saveCache(cache); err != nil {
		logging.Debug(context.Background(), "version check: failed to save cache",
			"error", err.Error())
	}

	// Show notification if outdated
	if isOutdated(currentVersion, latestVersion) {
		printNotification(cmd, currentVersion, latestVersion)
	}
}

// globalConfigDirPath returns the expanded path to the global config directory (~/.entire).
func globalConfigDirPath() (string, error) {
	home, err := os.UserHomeDir()
	if err != nil {
		return "", fmt.Errorf("getting home directory: %w", err)
	}
	return filepath.Join(home, globalConfigDirName), nil
}

// ensureGlobalConfigDir creates the global config directory if it doesn't exist.
func ensureGlobalConfigDir() error {
	configDir, err := globalConfigDirPath()
	if err != nil {
		return err
	}

	//nolint:gosec // ~/.entire is user home directory, 0o755 is appropriate
	if err := os.MkdirAll(configDir, 0o755); err != nil {
		return fmt.Errorf("creating config directory: %w", err)
	}

	return nil
}

// cacheFilePath returns the full path to the version check cache file.
func cacheFilePath() (string, error) {
	configDir, err := globalConfigDirPath()
	if err != nil {
		return "", err
	}
	return filepath.Join(configDir, cacheFileName), nil
}

// loadCache loads the version check cache from disk.
// Returns an error if the file doesn't exist or is corrupted.
func loadCache() (*VersionCache, error) {
	filePath, err := cacheFilePath()
	if err != nil {
		return nil, err
	}

	data, err := os.ReadFile(filePath) //nolint:gosec // cacheFilePath is safe
	if err != nil {
		return nil, fmt.Errorf("reading cache file: %w", err)
	}

	var cache VersionCache
	if err := json.Unmarshal(data, &cache); err != nil {
		return nil, fmt.Errorf("parsing cache: %w", err)
	}

	return &cache, nil
}

// saveCache saves the version check cache to disk.
// Uses atomic write semantics (write to temp file, then rename).
func saveCache(cache *VersionCache) error {
	filePath, err := cacheFilePath()
	if err != nil {
		return err
	}

	// Marshal to JSON
	data, err := json.MarshalIndent(cache, "", "  ")
	if err != nil {
		return fmt.Errorf("marshaling cache: %w", err)
	}

	// Write to temp file first (atomic write)
	dir := filepath.Dir(filePath)
	tmpFile, err := os.CreateTemp(dir, ".version_check_tmp_")
	if err != nil {
		return fmt.Errorf("creating temp file: %w", err)
	}
	defer os.Remove(tmpFile.Name())

	if _, err := tmpFile.Write(data); err != nil {
		_ = tmpFile.Close() // cleanup on error path
		return fmt.Errorf("writing cache: %w", err)
	}

	if err := tmpFile.Close(); err != nil {
		return fmt.Errorf("closing temp file: %w", err)
	}

	// Rename temp file to final location
	if err := os.Rename(tmpFile.Name(), filePath); err != nil {
		return fmt.Errorf("renaming cache file: %w", err)
	}

	return nil
}


// fetchLatestVersion fetches the latest version from the GitHub API.
// Returns a timeout-safe version check with a 1-second timeout.
func fetchLatestVersion() (string, error) {
	// Create a context with timeout for the HTTP request
	ctx, cancel := context.WithTimeout(context.Background(), httpTimeout)
	defer cancel()

	req, err := http.NewRequestWithContext(ctx, http.MethodGet, githubAPIURL, nil)
	if err != nil {
		return "", fmt.Errorf("creating request: %w", err)
	}

	// Set headers to identify as Entire CLI
	req.Header.Set("Accept", "application/vnd.github+json")
	req.Header.Set("User-Agent", "entire-cli")

	client := &http.Client{}
	resp, err := client.Do(req)
	if err != nil {
		return "", fmt.Errorf("fetching release info: %w", err)
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		return "", fmt.Errorf("unexpected status code: %d", resp.StatusCode)
	}

	// Read response body (limit to prevent large reads)
	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return "", fmt.Errorf("reading response: %w", err)
	}

	// Parse GitHub release response
	version, err := parseGitHubRelease(body)
	if err != nil {
		return "", fmt.Errorf("parsing release: %w", err)
	}

	return version, nil
}

// parseGitHubRelease parses the GitHub API response and extracts the latest stable version.
// Filters out prerelease versions.
func parseGitHubRelease(body []byte) (string, error) {
	var release GitHubRelease
	if err := json.Unmarshal(body, &release); err != nil {
		return "", fmt.Errorf("parsing JSON: %w", err)
	}

	// Skip prerelease versions
	if release.Prerelease {
		return "", errors.New("only prerelease versions available")
	}

	// Ensure we have a tag name
	if release.TagName == "" {
		return "", errors.New("empty tag name")
	}

	return release.TagName, nil
}

// isOutdated compares current and latest versions using semantic versioning.
// Returns true if current < latest.
// Handles pre-release versions (e.g., 1.0.0rc1 < 1.0.0).
func isOutdated(current, latest string) bool {
	// Skip if either version is empty
	if current == "" || latest == "" {
		return false
	}

	// Skip if versions are the same
	if current == latest {
		return false
	}

	// Parse versions
	currParts, currIsPrerelease, err := parseVersionWithPrerelease(current)
	if err != nil {
		return false
	}

	latestParts, latestIsPrerelease, err := parseVersionWithPrerelease(latest)
	if err != nil {
		return false
	}

	// Compare major.minor.patch as integers
	for i := range 3 {
		//nolint:gosec // G602 false positive: array size is [3], loop range is 3
		if currParts[i] < latestParts[i] {
			return true
		}
		if currParts[i] > latestParts[i] {
			return false
		}
	}

	// If base versions are equal but one is a pre-release, the stable version is newer
	if currParts == latestParts {
		// If current is pre-release but latest is not, current is outdated
		if currIsPrerelease && !latestIsPrerelease {
			return true
		}
	}

	return false
}

// parseVersionWithPrerelease parses a semantic version string and returns [major, minor, patch] and
// whether it's a pre-release version. Strips the "v" prefix if present.
// Pre-release versions are identified by non-numeric suffixes in the patch version (e.g., "1.0.0rc1").
func parseVersionWithPrerelease(version string) ([3]int, bool, error) {
	var parts [3]int

	// Strip "v" prefix
	version = strings.TrimPrefix(version, "v")

	// Split by dots
	pieces := strings.Split(version, ".")
	if len(pieces) < 1 {
		return parts, false, errors.New("invalid version format")
	}

	isPrerelease := false

	// Parse first three parts as integers
	for i := 0; i < 3 && i < len(pieces); i++ {
		// Extract only numeric prefix (e.g., "1rc1" → "1")
		numStr := ""
		hasNonNumeric := false
		var numStrSb336 strings.Builder
		for _, ch := range pieces[i] {
			if ch >= '0' && ch <= '9' {
				numStrSb336.WriteRune(ch)
			} else {
				hasNonNumeric = true
				break
			}
		}
		numStr += numStrSb336.String()

		// If the last part (patch) has non-numeric suffix, it's a pre-release
		if i == 2 && hasNonNumeric {
			isPrerelease = true
		}

		if numStr == "" {
			// No numeric part found, default to 0
			parts[i] = 0
			continue
		}

		num, err := strconv.Atoi(numStr)
		if err != nil {
			return parts, false, fmt.Errorf("parsing version part %d: %w", i, err)
		}
		parts[i] = num
	}

	return parts, isPrerelease, nil
}

// printNotification prints the version update notification to the user.
func printNotification(cmd *cobra.Command, current, latest string) {
	msg := fmt.Sprintf("\nA newer version of Entire CLI is available: %s (current: %s)\nRun 'brew upgrade entire' to update.\n",
		latest, current)
	fmt.Fprint(cmd.OutOrStdout(), msg)
}

